#include<stdio.h>
#include<string.h>
#include<stdlib.h>

int main(int argc, char *argv[])
{
    char str[102];
    int p[4],n[4],d[4];
    long long int min,r;
    while(~scanf("%s",str))
    {
        int i;
        min=101;
        d[0]=d[1]=d[2]=0;
        for(i=0; i<3; i++)
        {
            scanf("%d",&n[i]);
        }
        for(i=0; i<3; i++)
        {
            scanf("%d",&p[i]);
        }
        scanf("%lld",&r);
        i=strlen(str)-1;
        for(; i>=0; i--)
        {
            if(str[i]=='B')d[0]++;
            else if(str[i]=='S')d[1]++;
            else if(str[i]=='C')d[2]++;
        }
        for(i=0; i<3; i++)
        {
            if(d[i]!=0&&(n[i]/d[i])<min)
                min=n[i]/d[i];
        }
        if(min==101)min=0;
        for(i=0; i<3; i++)
            n[i]=n[i]-d[i]*min;
        // Replace the slow while loop with a binary search for the number of extra burgers
        long long sum_cost = 0, value_stock = 0;
        for(i=0;i<3;i++) {
            sum_cost += (long long)p[i] * d[i];
            value_stock += (long long)p[i] * n[i];
        }
        long long high;
        if (sum_cost == 0) {
            // Should never happen for a valid recipe, but avoid division by zero.
            high = 1000000000000000000LL;
        } else {
            high = (r + value_stock) / sum_cost + 1;
        }
        long long lo = 0, hi = high;
        while (lo < hi) {
            long long mid = lo + (hi - lo + 1) / 2;
            long long cost = 0;
            for(i=0;i<3;i++) {
                long long need = mid * (long long)d[i];
                if (need > n[i]) {
                    cost += (long long)p[i] * (need - n[i]);
                }
            }
            if (cost <= r) {
                lo = mid;
            } else {
                hi = mid - 1;
            }
        }
        min += lo;
        printf("%lld\n", min);
    }
    return 0;
}

